insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000911', '40000000-0000-4000-8000-000000900091', 'A', '$-1$', 1), ('50000000-0000-4000-8000-000009000912', '40000000-0000-4000-8000-000000900091', 'B', '$1$', 2), ('50000000-0000-4000-8000-000009000913', '40000000-0000-4000-8000-000000900091', 'C', '$7$', 3), ('50000000-0000-4000-8000-000009000914', '40000000-0000-4000-8000-000000900091', 'D', '$-7$', 4)
