insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000911', '40000000-0000-4000-8000-000000900091', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000912', '40000000-0000-4000-8000-000000900091', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000913', '40000000-0000-4000-8000-000000900091', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900091', '$-1$', 'O produto interno usual soma os produtos das componentes correspondentes. Aqui os termos são três, zero e menos quatro, cuja soma é menos um. $3+0-4=-1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000911', '40000000-0000-4000-8000-000000900091', 'Multiplique a primeira componente', '$1\cdot3=3$.', 1), ('70000000-0000-4000-8000-000009000912', '40000000-0000-4000-8000-000000900091', 'Multiplique a segunda', '$2\cdot0=0$.', 2), ('70000000-0000-4000-8000-000009000913', '40000000-0000-4000-8000-000000900091', 'Multiplique a terceira', '$(-1)\cdot4=-4$.', 3), ('70000000-0000-4000-8000-000009000914', '40000000-0000-4000-8000-000000900091', 'Some', '$3+0-4=-1$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900092', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'easy', 'published', 'Qual é a norma euclidiana de $(2,-3,6)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000921', '40000000-0000-4000-8000-000000900092', 'A', '$5$', 1), ('50000000-0000-4000-8000-000009000922', '40000000-0000-4000-8000-000000900092', 'B', '$7$', 2), ('50000000-0000-4000-8000-000009000923', '40000000-0000-4000-8000-000000900092', 'C', '$11$', 3), ('50000000-0000-4000-8000-000009000924', '40000000-0000-4000-8000-000000900092', 'D', '$49$', 4)
