insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000921', '40000000-0000-4000-8000-000000900092', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000922', '40000000-0000-4000-8000-000000900092', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000923', '40000000-0000-4000-8000-000000900092', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900092', '$7$', 'A norma é a raiz quadrada da soma dos quadrados das componentes. A soma é quarenta e nove, cuja raiz positiva é sete. A norma vale $7$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000921', '40000000-0000-4000-8000-000000900092', 'Eleve ao quadrado', '$2^2=4$, $(-3)^2=9$ e $6^2=36$.', 1), ('70000000-0000-4000-8000-000009000922', '40000000-0000-4000-8000-000000900092', 'Some', '$4+9+36=49$.', 2), ('70000000-0000-4000-8000-000009000923', '40000000-0000-4000-8000-000000900092', 'Extraia a raiz', '$\sqrt{49}=7$.', 3), ('70000000-0000-4000-8000-000009000924', '40000000-0000-4000-8000-000000900092', 'Conclua', 'A norma vale $7$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900093', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'easy', 'published', 'Qual é a distância entre $a=(1,4)$ e $b=(-2,0)$ no plano euclidiano?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000931', '40000000-0000-4000-8000-000000900093', 'A', '$\sqrt7$', 1), ('50000000-0000-4000-8000-000009000932', '40000000-0000-4000-8000-000000900093', 'B', '$25$', 2), ('50000000-0000-4000-8000-000009000933', '40000000-0000-4000-8000-000000900093', 'C', '$5$', 3), ('50000000-0000-4000-8000-000009000934', '40000000-0000-4000-8000-000000900093', 'D', '$7$', 4)
