insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000931', '40000000-0000-4000-8000-000000900093', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000932', '40000000-0000-4000-8000-000000900093', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000933', '40000000-0000-4000-8000-000000900093', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900093', '$5$', 'A distância é a norma da diferença entre os pontos. O vetor diferença possui componentes três e quatro, formando o conhecido triângulo retângulo de hipotenusa cinco. A distância é $5$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000931', '40000000-0000-4000-8000-000000900093', 'Subtraia os pontos', '$a-b=(3,4)$.', 1), ('70000000-0000-4000-8000-000009000932', '40000000-0000-4000-8000-000000900093', 'Calcule os quadrados', '$3^2+4^2=9+16$.', 2), ('70000000-0000-4000-8000-000009000933', '40000000-0000-4000-8000-000000900093', 'Extraia a raiz', '$\sqrt{25}=5$.', 3), ('70000000-0000-4000-8000-000009000934', '40000000-0000-4000-8000-000000900093', 'Conclua', 'A distância é $5$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900094', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'easy', 'published', 'Qual vetor é ortogonal a $(2,1)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000941', '40000000-0000-4000-8000-000000900094', 'A', '$(1,2)$', 1), ('50000000-0000-4000-8000-000009000942', '40000000-0000-4000-8000-000000900094', 'B', '$(2,-1)$', 2), ('50000000-0000-4000-8000-000009000943', '40000000-0000-4000-8000-000000900094', 'C', '$(0,1)$', 3), ('50000000-0000-4000-8000-000009000944', '40000000-0000-4000-8000-000000900094', 'D', '$(1,-2)$', 4)
