insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000941', '40000000-0000-4000-8000-000000900094', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000942', '40000000-0000-4000-8000-000000900094', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000943', '40000000-0000-4000-8000-000000900094', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900094', '$(1,-2)$', 'Dois vetores são ortogonais quando seu produto interno é zero. O produto de $(2,1)$ por $(1,-2)$ soma dois e menos dois. O vetor correto é $(1,-2)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000941', '40000000-0000-4000-8000-000000900094', 'Escolha o candidato', 'Considere $(1,-2)$.', 1), ('70000000-0000-4000-8000-000009000942', '40000000-0000-4000-8000-000000900094', 'Calcule o produto', '$2\cdot1+1\cdot(-2)=0$.', 2), ('70000000-0000-4000-8000-000009000943', '40000000-0000-4000-8000-000000900094', 'Interprete', 'Produto interno zero significa ortogonalidade.', 3), ('70000000-0000-4000-8000-000009000944', '40000000-0000-4000-8000-000000900094', 'Conclua', 'O vetor correto é $(1,-2)$.', 4)
