insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000951', '40000000-0000-4000-8000-000000900095', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000952', '40000000-0000-4000-8000-000000900095', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000953', '40000000-0000-4000-8000-000000900095', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900095', '$(3,0)$', 'Projetar sobre o eixo horizontal preserva a componente nessa direção e remove a componente vertical. Portanto a segunda coordenada se torna zero. A projeção é $(3,0)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000951', '40000000-0000-4000-8000-000000900095', 'Identifique o subespaço', 'O eixo $x$ é gerado por $(1,0)$.', 1), ('70000000-0000-4000-8000-000009000952', '40000000-0000-4000-8000-000000900095', 'Preserve a componente paralela', 'A componente horizontal é $3$.', 2), ('70000000-0000-4000-8000-000009000953', '40000000-0000-4000-8000-000000900095', 'Elimine a perpendicular', 'A componente vertical vira $0$.', 3), ('70000000-0000-4000-8000-000009000954', '40000000-0000-4000-8000-000000900095', 'Conclua', 'A projeção é $(3,0)$.', 4)
