insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000961', '40000000-0000-4000-8000-000000900096', 'A', '$-17$', 1), ('50000000-0000-4000-8000-000009000962', '40000000-0000-4000-8000-000000900096', 'B', '$-1$', 2), ('50000000-0000-4000-8000-000009000963', '40000000-0000-4000-8000-000000900096', 'C', '$1$', 3), ('50000000-0000-4000-8000-000009000964', '40000000-0000-4000-8000-000000900096', 'D', '$17$', 4)
