insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900096', '$-1$', 'Avaliar uma forma quadrática exige substituir as coordenadas e respeitar os quadrados. O primeiro termo vale oito e o segundo vale nove. $Q(2,3)=-1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000961', '40000000-0000-4000-8000-000000900096', 'Substitua $x$', '$2(2^2)=8$.', 1), ('70000000-0000-4000-8000-000009000962', '40000000-0000-4000-8000-000000900096', 'Substitua $y$', '$3^2=9$.', 2), ('70000000-0000-4000-8000-000009000963', '40000000-0000-4000-8000-000000900096', 'Faça a diferença', '$8-9=-1$.', 3), ('70000000-0000-4000-8000-000009000964', '40000000-0000-4000-8000-000000900096', 'Conclua', '$Q(2,3)=-1$.', 4)
