insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000971', '40000000-0000-4000-8000-000000900097', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000972', '40000000-0000-4000-8000-000000900097', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000973', '40000000-0000-4000-8000-000000900097', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900097', '$90^circ$', 'O produto interno dos vetores é zero e ambos são não nulos. Essa condição caracteriza um ângulo reto no espaço euclidiano. $	heta=90^circ$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000971', '40000000-0000-4000-8000-000000900097', 'Calcule o produto', '$1\cdot1+1\cdot(-1)=0$.', 1), ('70000000-0000-4000-8000-000009000972', '40000000-0000-4000-8000-000000900097', 'Observe as normas', 'Ambas são positivas.', 2), ('70000000-0000-4000-8000-000009000973', '40000000-0000-4000-8000-000000900097', 'Use a fórmula', '$cos	heta=0$.', 3), ('70000000-0000-4000-8000-000009000974', '40000000-0000-4000-8000-000000900097', 'Conclua', '$	heta=90^circ$.', 4)
