insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000981', '40000000-0000-4000-8000-000000900098', 'A', '$(1/2,1/2)$', 1), ('50000000-0000-4000-8000-000009000982', '40000000-0000-4000-8000-000000900098', 'B', '$(2,2)$', 2), ('50000000-0000-4000-8000-000009000983', '40000000-0000-4000-8000-000000900098', 'C', '$(3,3)$', 3), ('50000000-0000-4000-8000-000009000984', '40000000-0000-4000-8000-000000900098', 'D', '$(5/2,5/2)$', 4)
