insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900098', '$(5/2,5/2)$', 'A projeção sobre uma reta é $(vcdot u)/(ucdot u)$ vezes o vetor diretor. O coeficiente é cinco meios. A projeção é $(5/2,5/2)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000981', '40000000-0000-4000-8000-000000900098', 'Calcule o numerador', '$vcdot u=2+3=5$.', 1), ('70000000-0000-4000-8000-000009000982', '40000000-0000-4000-8000-000000900098', 'Calcule o denominador', '$ucdot u=1+1=2$.', 2), ('70000000-0000-4000-8000-000009000983', '40000000-0000-4000-8000-000000900098', 'Forme o coeficiente', '$5/2$.', 3), ('70000000-0000-4000-8000-000009000984', '40000000-0000-4000-8000-000000900098', 'Multiplique', 'A projeção é $(5/2,5/2)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900099', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'medium', 'published', 'Ao aplicar Gram–Schmidt a $v_1=(1,0)$ e $v_2=(1,2)$, qual segundo vetor ortogonal é obtido antes da normalização?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000991', '40000000-0000-4000-8000-000000900099', 'A', '$(0,2)$', 1), ('50000000-0000-4000-8000-000009000992', '40000000-0000-4000-8000-000000900099', 'B', '$(1,2)$', 2), ('50000000-0000-4000-8000-000009000993', '40000000-0000-4000-8000-000000900099', 'C', '$(1,0)$', 3), ('50000000-0000-4000-8000-000009000994', '40000000-0000-4000-8000-000000900099', 'D', '$(-2,0)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900099', '50000000-0000-4000-8000-000009000991') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900099', '30000000-0000-4000-8000-000000090021', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000991', '40000000-0000-4000-8000-000000900099', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009000992', '40000000-0000-4000-8000-000000900099', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009000993', '40000000-0000-4000-8000-000000900099', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900099', '$(0,2)$', 'Subtrai-se de $v_2$ sua projeção sobre o primeiro vetor. A projeção é $(1,0)$, deixando apenas a componente vertical. $u_1\cdot u_2=0$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000991', '40000000-0000-4000-8000-000000900099', 'Mantenha o primeiro', '$u_1=(1,0)$.', 1), ('70000000-0000-4000-8000-000009000992', '40000000-0000-4000-8000-000000900099', 'Projete', '$\operatorname{proj}_{u_1}v_2=(1,0)$.', 2), ('70000000-0000-4000-8000-000009000993', '40000000-0000-4000-8000-000000900099', 'Subtraia', '$u_2=(1,2)-(1,0)=(0,2)$.', 3), ('70000000-0000-4000-8000-000009000994', '40000000-0000-4000-8000-000000900099', 'Confira', '$u_1\cdot u_2=0$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900100', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'medium', 'published', 'Em $\mathbb R^3$, qual é o complemento ortogonal de $W=\operatorname{span}\{(1,1,0),(0,1,1)\}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001001', '40000000-0000-4000-8000-000000900100', 'A', '$\{0\}$', 1), ('50000000-0000-4000-8000-000009001002', '40000000-0000-4000-8000-000000900100', 'B', '$\operatorname{span}\{(1,-1,1)\}$', 2), ('50000000-0000-4000-8000-000009001003', '40000000-0000-4000-8000-000000900100', 'C', '$\operatorname{span}\{(1,1,1)\}$', 3), ('50000000-0000-4000-8000-000009001004', '40000000-0000-4000-8000-000000900100', 'D', '$\operatorname{span}\{(1,0,-1)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900100', '50000000-0000-4000-8000-000009001002') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900100', '30000000-0000-4000-8000-000000090021', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001001', '40000000-0000-4000-8000-000000900100', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001002', '40000000-0000-4000-8000-000000900100', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001003', '40000000-0000-4000-8000-000000900100', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900100', '$\operatorname{span}\{(1,-1,1)\}$', 'Um vetor do complemento deve ser ortogonal aos dois geradores. As equações impõem $y=-x$ e $z=x$, produzindo a direção indicada. $W^\perp=\operatorname{span}\{(1,-1,1)\}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001001', '40000000-0000-4000-8000-000000900100', 'Imponha a primeira ortogonalidade', '$x+y=0$.', 1), ('70000000-0000-4000-8000-000009001002', '40000000-0000-4000-8000-000000900100', 'Imponha a segunda', '$y+z=0$.', 2), ('70000000-0000-4000-8000-000009001003', '40000000-0000-4000-8000-000000900100', 'Parametrize', '$y=-x$ e $z=x$.', 3), ('70000000-0000-4000-8000-000009001004', '40000000-0000-4000-8000-000000900100', 'Conclua', '$W^\perp=\operatorname{span}\{(1,-1,1)\}$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900101', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'medium', 'published', 'Qual constante $c$ minimiza $(c-1)^2+(c-4)^2+(c-7)^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001011', '40000000-0000-4000-8000-000000900101', 'A', '$5$', 1), ('50000000-0000-4000-8000-000009001012', '40000000-0000-4000-8000-000000900101', 'B', '$12$', 2), ('50000000-0000-4000-8000-000009001013', '40000000-0000-4000-8000-000000900101', 'C', '$4$', 3), ('50000000-0000-4000-8000-000009001014', '40000000-0000-4000-8000-000000900101', 'D', '$3$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900101', '50000000-0000-4000-8000-000009001013') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
