insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001011', '40000000-0000-4000-8000-000000900101', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001012', '40000000-0000-4000-8000-000000900101', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001013', '40000000-0000-4000-8000-000000900101', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900101', '$4$', 'O melhor ajuste constante em mínimos quadrados é a média dos dados. A soma dos três valores é doze e sua média é quatro. A segunda derivada é positiva.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001011', '40000000-0000-4000-8000-000000900101', 'Derive a função', '$2(c-1)+2(c-4)+2(c-7)=0$.', 1), ('70000000-0000-4000-8000-000009001012', '40000000-0000-4000-8000-000000900101', 'Simplifique', '$6c-24=0$.', 2), ('70000000-0000-4000-8000-000009001013', '40000000-0000-4000-8000-000000900101', 'Resolva', '$c=4$.', 3), ('70000000-0000-4000-8000-000009001014', '40000000-0000-4000-8000-000000900101', 'Confira', 'A segunda derivada é positiva.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900102', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'medium', 'published', 'Como se classifica $Q(x,y)=3x^2+2y^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001021', '40000000-0000-4000-8000-000000900102', 'A', 'Negativa definida', 1), ('50000000-0000-4000-8000-000009001022', '40000000-0000-4000-8000-000000900102', 'B', 'Indefinida', 2), ('50000000-0000-4000-8000-000009001023', '40000000-0000-4000-8000-000000900102', 'C', 'Semidefinida negativa', 3), ('50000000-0000-4000-8000-000009001024', '40000000-0000-4000-8000-000000900102', 'D', 'Positiva definida', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900102', '50000000-0000-4000-8000-000009001024') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900102', '30000000-0000-4000-8000-000000090023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001021', '40000000-0000-4000-8000-000000900102', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001022', '40000000-0000-4000-8000-000000900102', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001023', '40000000-0000-4000-8000-000000900102', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900102', 'Positiva definida', 'Ambos os coeficientes diagonais são positivos e não há termo misto. Para todo vetor não nulo, pelo menos um quadrado contribui positivamente. $Q(x,y)>0$ fora da origem.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001021', '40000000-0000-4000-8000-000000900102', 'Observe os coeficientes', '$3>0$ e $2>0$.', 1), ('70000000-0000-4000-8000-000009001022', '40000000-0000-4000-8000-000000900102', 'Use os quadrados', '$x^2,y^2\ge0$.', 2), ('70000000-0000-4000-8000-000009001023', '40000000-0000-4000-8000-000000900102', 'Teste não nulidade', 'Se $(x,y)\ne0$, ao menos um termo é positivo.', 3), ('70000000-0000-4000-8000-000009001024', '40000000-0000-4000-8000-000000900102', 'Conclua', '$Q(x,y)>0$ fora da origem.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900103', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'hard', 'published', 'No produto interno $\langle x,y\rangle_G=x^TGy$, com $G=\operatorname{diag}(2,1)$, qual é a norma de $(1,2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001031', '40000000-0000-4000-8000-000000900103', 'A', '$\sqrt6$', 1), ('50000000-0000-4000-8000-000009001032', '40000000-0000-4000-8000-000000900103', 'B', '$\sqrt5$', 2), ('50000000-0000-4000-8000-000009001033', '40000000-0000-4000-8000-000000900103', 'C', '$3$', 3), ('50000000-0000-4000-8000-000009001034', '40000000-0000-4000-8000-000000900103', 'D', '$6$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900103', '50000000-0000-4000-8000-000009001031') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900103', '30000000-0000-4000-8000-000000090020', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001031', '40000000-0000-4000-8000-000000900103', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001032', '40000000-0000-4000-8000-000000900103', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001033', '40000000-0000-4000-8000-000000900103', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900103', '$\sqrt6$', 'A norma induzida é a raiz de $x^TGx$. A ponderação duplica o quadrado da primeira coordenada e mantém o da segunda. A norma é $\sqrt6$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001031', '40000000-0000-4000-8000-000000900103', 'Aplique a matriz', '$G(1,2)=(2,2)$.', 1), ('70000000-0000-4000-8000-000009001032', '40000000-0000-4000-8000-000000900103', 'Faça o produto', '$(1,2)\cdot(2,2)=2+4=6$.', 2), ('70000000-0000-4000-8000-000009001033', '40000000-0000-4000-8000-000000900103', 'Extraia a raiz', '$\|x\|_G=\sqrt6$.', 3), ('70000000-0000-4000-8000-000009001034', '40000000-0000-4000-8000-000000900103', 'Conclua', 'A norma é $\sqrt6$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900104', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'hard', 'published', 'Em $P_2$ com $\langle p,q\rangle=\int_{-1}^1p(x)q(x)\,dx$, qual polinômio obtido de $x^2$ é ortogonal a $1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001041', '40000000-0000-4000-8000-000000900104', 'A', '$x^2+1/3$', 1), ('50000000-0000-4000-8000-000009001042', '40000000-0000-4000-8000-000000900104', 'B', '$x^2-1/3$', 2), ('50000000-0000-4000-8000-000009001043', '40000000-0000-4000-8000-000000900104', 'C', '$x^2-1/2$', 3), ('50000000-0000-4000-8000-000009001044', '40000000-0000-4000-8000-000000900104', 'D', '$x^2-x$', 4)
