insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001041', '40000000-0000-4000-8000-000000900104', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001042', '40000000-0000-4000-8000-000000900104', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001043', '40000000-0000-4000-8000-000000900104', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900104', '$x^2-1/3$', 'Retira-se de $x^2$ sua projeção sobre o polinômio constante. O coeficiente é a razão entre as integrais de $x^2$ e de um, igual a um terço. $x^2-1/3$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001041', '40000000-0000-4000-8000-000000900104', 'Calcule o numerador', '$\int_{-1}^1x^2dx=2/3$.', 1), ('70000000-0000-4000-8000-000009001042', '40000000-0000-4000-8000-000000900104', 'Calcule o denominador', '$\int_{-1}^11dx=2$.', 2), ('70000000-0000-4000-8000-000009001043', '40000000-0000-4000-8000-000000900104', 'Forme a projeção', '$((2/3)/2)\cdot1=1/3$.', 3), ('70000000-0000-4000-8000-000009001044', '40000000-0000-4000-8000-000000900104', 'Subtraia', '$x^2-1/3$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900105', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'hard', 'published', 'Qual reta $y=a+bx$ ajusta por mínimos quadrados os pontos $(0,1),(1,2),(2,2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001051', '40000000-0000-4000-8000-000000900105', 'A', '$y=4/3+x/3$', 1), ('50000000-0000-4000-8000-000009001052', '40000000-0000-4000-8000-000000900105', 'B', '$y=1+x/2$', 2), ('50000000-0000-4000-8000-000009001053', '40000000-0000-4000-8000-000000900105', 'C', '$y=7/6+x/2$', 3), ('50000000-0000-4000-8000-000009001054', '40000000-0000-4000-8000-000000900105', 'D', '$y=1+x$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900105', '50000000-0000-4000-8000-000009001053') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900105', '30000000-0000-4000-8000-000000090022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001051', '40000000-0000-4000-8000-000000900105', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001052', '40000000-0000-4000-8000-000000900105', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001053', '40000000-0000-4000-8000-000000900105', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900105', '$y=7/6+x/2$', 'As equações normais usam as somas dos valores, dos quadrados e dos produtos. Resolver o sistema fornece intercepto sete sextos e inclinação um meio. $3a+3/2=5$, então $a=7/6$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001051', '40000000-0000-4000-8000-000000900105', 'Monte a primeira equação', '$3a+3b=5$.', 1), ('70000000-0000-4000-8000-000009001052', '40000000-0000-4000-8000-000000900105', 'Monte a segunda', '$3a+5b=6$.', 2), ('70000000-0000-4000-8000-000009001053', '40000000-0000-4000-8000-000000900105', 'Subtraia', '$2b=1$, então $b=1/2$.', 3), ('70000000-0000-4000-8000-000009001054', '40000000-0000-4000-8000-000000900105', 'Recupere $a$', '$3a+3/2=5$, então $a=7/6$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900106', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'hard', 'published', 'Se $A=QR$ tem colunas independentes e $Q^TQ=I$, qual sistema triangular produz a solução de mínimos quadrados de $Ax\approx b$?')
