insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001061', '40000000-0000-4000-8000-000000900106', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001062', '40000000-0000-4000-8000-000000900106', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001063', '40000000-0000-4000-8000-000000900106', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900106', '$Rx=Q^Tb$', 'A ortogonalidade de $Q$ transforma as equações normais sem formar $A^TA$. Como $R$ é triangular e invertível, resta resolver o sistema indicado. $Rx=Q^Tb$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001061', '40000000-0000-4000-8000-000000900106', 'Escreva a fatoração', '$A=QR$.', 1), ('70000000-0000-4000-8000-000009001062', '40000000-0000-4000-8000-000000900106', 'Projete a equação', '$Q^TAx=Q^Tb$.', 2), ('70000000-0000-4000-8000-000009001063', '40000000-0000-4000-8000-000000900106', 'Simplifique', '$Q^TQRx=Rx$.', 3), ('70000000-0000-4000-8000-000009001064', '40000000-0000-4000-8000-000000900106', 'Conclua', '$Rx=Q^Tb$.', 4)
