insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001071', '40000000-0000-4000-8000-000000900107', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001072', '40000000-0000-4000-8000-000000900107', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001073', '40000000-0000-4000-8000-000000900107', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900107', '$3$ e $1$', 'A matriz simétrica da forma tem elementos diagonais iguais a dois e elementos fora da diagonal iguais a um. Seus autovalores são os extremos na circunferência unitária. Máximo $3$ e mínimo $1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001071', '40000000-0000-4000-8000-000000900107', 'Monte a matriz', '$S=\begin{pmatrix}2&1\\1&2\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009001072', '40000000-0000-4000-8000-000000900107', 'Ache o polinômio', '$\det(\lambda I-S)=(\lambda-2)^2-1$.', 2), ('70000000-0000-4000-8000-000009001073', '40000000-0000-4000-8000-000000900107', 'Resolva', 'Os autovalores são $3$ e $1$.', 3), ('70000000-0000-4000-8000-000009001074', '40000000-0000-4000-8000-000000900107', 'Interprete', 'Máximo $3$ e mínimo $1$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900108', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090006', 'multiple_choice', 'hard', 'published', 'Qual é o mínimo de $Q(x,y)=x^2+4y^2$ sujeito a $x+y=1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009001081', '40000000-0000-4000-8000-000000900108', 'A', '$4$', 1), ('50000000-0000-4000-8000-000009001082', '40000000-0000-4000-8000-000000900108', 'B', '$4/5$', 2), ('50000000-0000-4000-8000-000009001083', '40000000-0000-4000-8000-000000900108', 'C', '$1$', 3), ('50000000-0000-4000-8000-000009001084', '40000000-0000-4000-8000-000000900108', 'D', '$1/2$', 4)
