insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009001081', '40000000-0000-4000-8000-000000900108', 'Identifique a definição ou decomposição geométrica que se aplica.', 1), ('60000000-0000-4000-8000-000009001082', '40000000-0000-4000-8000-000000900108', 'Calcule cada produto ou coeficiente separadamente.', 2), ('60000000-0000-4000-8000-000009001083', '40000000-0000-4000-8000-000000900108', 'Verifique sinal, dimensão e ortogonalidade no resultado.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900108', '$4/5$', 'Substituir a restrição reduz o problema a uma quadrática convexa em uma variável. Seu vértice ocorre em $y=1/5$ e produz quatro quintos. $x=4/5$ e $Q=16/25+4/25=4/5$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009001081', '40000000-0000-4000-8000-000000900108', 'Elimine uma variável', '$x=1-y$.', 1), ('70000000-0000-4000-8000-000009001082', '40000000-0000-4000-8000-000000900108', 'Substitua', '$Q=(1-y)^2+4y^2=1-2y+5y^2$.', 2), ('70000000-0000-4000-8000-000009001083', '40000000-0000-4000-8000-000000900108', 'Ache o vértice', '$-2+10y=0$, logo $y=1/5$.', 3), ('70000000-0000-4000-8000-000009001084', '40000000-0000-4000-8000-000000900108', 'Avalie', '$x=4/5$ e $Q=16/25+4/25=4/5$.', 4)
